"""Seed MITRE ATT&CK Enterprise techniques into ttps table.

Revision ID: 019_seed_mitre_attack
Revises: 10cba6685383
Create Date: 2026-03-09
"""

import base64
import json
import uuid

import sqlalchemy as sa

from alembic import op

revision = "019_seed_mitre_attack"
down_revision = "10cba6685383"
branch_labels = None
depends_on = None

# MITRE ATT&CK Enterprise techniques, base64-encoded JSON
# Source: https://github.com/mitre-attack/attack-stix-data (enterprise-attack.json)
# fmt: off
_MITRE_B64 = ""
# fmt: on


def _load_techniques() -> list[dict]:
    return json.loads(base64.b64decode(_MITRE_B64))


def upgrade() -> None:
    conn = op.get_bind()
    ttps = sa.table(
        "ttps",
        sa.column("id", sa.dialects.postgresql.UUID),
        sa.column("technique_id", sa.String),
        sa.column("technique_name", sa.String),
        sa.column("tactic", sa.String),
        sa.column("description", sa.Text),
        sa.column("article_count", sa.Integer),
    )

    # Get existing technique_ids to avoid duplicates
    existing = {row[0] for row in conn.execute(sa.select(ttps.c.technique_id)).fetchall()}

    techniques = _load_techniques()

    for t in techniques:
        tid = t["technique_id"]
        if tid in existing:
            # Update existing TTPs that are missing data
            conn.execute(
                ttps.update()
                .where(ttps.c.technique_id == tid)
                .where(
                    sa.or_(
                        ttps.c.description.is_(None),
                        ttps.c.description == "",
                    )
                )
                .values(
                    technique_name=t["technique_name"],
                    tactic=t["tactic"],
                    description=t["description"],
                )
            )
        else:
            conn.execute(
                ttps.insert().values(
                    id=str(uuid.uuid4()),
                    technique_id=tid,
                    technique_name=t["technique_name"],
                    tactic=t["tactic"],
                    description=t["description"],
                    article_count=0,
                )
            )


def downgrade() -> None:
    conn = op.get_bind()
    ttps = sa.table(
        "ttps",
        sa.column("technique_id", sa.String),
        sa.column("article_count", sa.Integer),
    )
    # Only remove TTPs that were seeded (never seen in articles)
    conn.execute(ttps.delete().where(ttps.c.article_count == 0))
